package com.ruoyi.paismart.application.intelligence;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ProviderInputBoundaryTest {
    ProviderService service;JdbcTemplate db;ControlledHttp http;
    @BeforeEach @SuppressWarnings("unchecked") void prepare(){db=mock(JdbcTemplate.class);http=mock(ControlledHttp.class);service=new ProviderService(db,mock(TransactionTemplate.class),http,mock(IntelligenceSettings.class),mock(ObjectProvider.class));}
    @Test void inlineKeyCannotBeSilentlyIgnoredOrStoredPlaintext(){assertThrows(IllegalArgumentException.class,()->service.save("LLM",Map.of("apiKey","test-only")));assertThrows(IllegalArgumentException.class,()->service.save("LLM",Map.of("config",Map.of("credentials",Map.of("accessKeySecret","test-only")))));verifyNoInteractions(db,http);}
    @Test void explicitPlatformProviderCodeAndActiveIntentSurviveAdaptation(){var result=service.adaptInput("LLM",Map.of("provider","QWEN展示名称","address","https://provider.invalid","config",Map.of("providerCode","dashscope"),"enabled",true,"active",false));assertEquals("dashscope",Values.map(result.get("config")).get("providerCode"));assertEquals(false,result.get("active"));assertFalse(result.containsKey("id"));verifyNoInteractions(db,http);}
    @Test void explicitProviderTestUsesChosenInactiveConfiguration(){var chosen=new ProviderService.Provider("chosen","LLM","名称","https://provider.invalid","model",0,"ai.paismart.test",true,false,1,Map.of());var test=spy(service);doReturn(chosen).when(test).get("chosen");doReturn(Map.of("state","READY")).when(test).test(2,"chosen","key");assertEquals("READY",test.testForScope(2,"LLM","chosen","key").get("state"));verify(test,never()).active(anyString());verify(test).test(2,"chosen","key");}
    @Test void chosenProviderCannotCrossCapabilityAndMissingIdRetainsActiveCompatibility(){var chosen=new ProviderService.Provider("chosen","EMBEDDING","名称","https://provider.invalid","model",2,"ai.paismart.test",true,true,1,Map.of());var test=spy(service);doReturn(chosen).when(test).get("chosen");assertThrows(IllegalArgumentException.class,()->test.testForScope(2,"LLM","chosen","key"));verify(test,never()).test(anyLong(),anyString(),anyString());doReturn(chosen).when(test).active("EMBEDDING");doReturn(Map.of("state","READY")).when(test).test(2,"chosen","key");assertEquals("READY",test.testForScope(2,"EMBEDDING","","key").get("state"));}
    @SuppressWarnings("unchecked") ProviderService persisted()throws Exception{var source=new org.h2.jdbcx.JdbcDataSource();source.setURL("jdbc:h2:mem:provider_"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");try(var c=source.getConnection()){org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(c,new org.springframework.core.io.ClassPathResource("db/paismart/V003__intelligence.sql"));org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(c,new org.springframework.core.io.ClassPathResource("db/paismart/V005__evaluation_datasets.sql"));}db=new JdbcTemplate(source);return new ProviderService(db,new TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(source)),http,mock(IntelligenceSettings.class),mock(ObjectProvider.class));}
    Map<String,Object> request(String endpoint,int dimension){return Map.of("name","名称","model","model","endpoint",endpoint,"dimension",dimension,"secretRef","ai.paismart.test","enabled",true,"active",false,"config",Map.of("providerCode","test"));}
    @Test void savingCompatibleOperationUrlPersistsBaseAddressBeforeAddressValidation()throws Exception{service=persisted();var saved=service.save("LLM",request("https://provider.invalid/v1/chat/completions/",0));String id=saved.get("id").toString();assertEquals("https://provider.invalid/v1",service.get(id).endpoint());assertEquals("https://provider.invalid/v1",db.queryForObject("SELECT endpoint FROM ps_provider WHERE id=?",String.class,id));verify(http).validated("https://provider.invalid/v1");var embedding=service.save("EMBEDDING",request("https://provider.invalid/v1/embeddings",2));assertEquals("https://provider.invalid/v1",service.get(embedding.get("id").toString()).endpoint());}
    @Test void loadingLegacyStoredSuffixNormalizesBothActiveConfigurationAndUiWithoutWritingItBack()throws Exception{service=persisted();var saved=service.save("LLM",request("https://provider.invalid/v1",0));String id=saved.get("id").toString();db.update("UPDATE ps_provider SET endpoint='https://provider.invalid/v1/chat/completions',active=TRUE WHERE id=?",id);assertEquals("https://provider.invalid/v1",service.active("LLM").endpoint());var row=service.list("LLM").get(0);assertEquals("https://provider.invalid/v1",row.get("address"));assertEquals("https://provider.invalid/v1/chat/completions",db.queryForObject("SELECT endpoint FROM ps_provider WHERE id=?",String.class,id));var restored=service.fromSnapshot(com.ruoyi.paismart.infrastructure.Jsons.write(Map.of("id",id,"scope","LLM","endpoint","https://provider.invalid/v1/chat/completions","revision",1)));assertEquals("https://provider.invalid/v1",restored.endpoint());}
}
